INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3000, "訓練はまだ\nここからですわ", 1000, 1, "vo_minigame_1013_icon_1_002_001", 2, 2, 2, "調子が上がって\nきたなっ", "vo_minigame_1013_icon_2_002_001");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3000, "クスクス、悪くない\n流れですわね", 5000, 2, "vo_minigame_1013_icon_1_003_001", 2, 2, 2, "ほらほら、\nまだいけるだろ？", "vo_minigame_1013_icon_2_003_001");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3000, "すばらしい\n記録ですわ", 10000, 3, "vo_minigame_1013_icon_1_004_001", 2, 3, 2, "へへっ、おまえら\nやるじゃねえか！", "vo_minigame_1013_icon_2_004_001");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3000, "乗りに乗って\nいますわね", 10000, 4, "vo_minigame_1013_icon_1_005_001", 2, 3, 3, "あたしたちはまだ\n止まらねえぜ！", "vo_minigame_1013_icon_2_005_001");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3000, "まだまだ行きます\nついてきなさい", 10000, 5, "vo_minigame_1013_icon_1_005_002", 2, 3, 3, "見てろよ！\nマコト班の快進撃だ！", "vo_minigame_1013_icon_2_005_002");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3000, "エリコ班の\n本領発揮ですわ！", 10000, 6, "vo_minigame_1013_icon_1_005_003", 2, 3, 3, "うおぉぉっ！\n絶好調だぜ！", "vo_minigame_1013_icon_2_005_003");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3000, "ここからは\n前人未到の領域です！", 0, 7, "vo_minigame_1013_icon_1_006_001", 2, 3, 4, "どこまで行けるか\n楽しみだなっ！", "vo_minigame_1013_icon_2_006_001");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (1000, "厄介でしたわ…", 1, 8, "vo_minigame_1013_icon_1_007_001", 3, 4, 5, "まだ諦めんなよっ", "vo_minigame_1013_icon_2_007_001");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (1000, "油断大敵です", 1, 9, "vo_minigame_1013_icon_1_007_002", 3, 4, 5, "冷やっとしたぜ…！", "vo_minigame_1013_icon_2_007_002");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (1000, "忌々しいっ…", 1, 10, "vo_minigame_1013_icon_1_007_003", 3, 4, 5, "弱音を吐くなっ", "vo_minigame_1013_icon_2_007_003");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (1500, "大所帯ですわね", 99, 11, "vo_minigame_1013_icon_1_008_001", 4, 3, 6, "マコト班集合！", "vo_minigame_1013_icon_2_008_001");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (1500, "エリコ班へようこそ", 99, 12, "vo_minigame_1013_icon_1_008_002", 4, 3, 6, "連携してくぞ！", "vo_minigame_1013_icon_2_008_002");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3000, "ナナカちゃんに\nお任せあれ", 0, 13, "vo_minigame_1013_icon_1_020_001", 1, 6, 8, "みんなに力を！", "vo_minigame_1013_icon_2_020_001");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3000, "はっはっは！\n任せろ！", 0, 14, "vo_minigame_1013_icon_1_022_001", 1, 7, 9, "任せてくれたまえ", "vo_minigame_1013_icon_2_022_001");
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3000, "どんどんいくわよ", 0, 15, "vo_minigame_1013_icon_1_023_001", 1, 8, 10, "ほな、いきまひょか", "vo_minigame_1013_icon_2_023_001");
